values ('f81b4810-0ad3-5c0d-b9ac-36b63d8358ca', null, '{"nl":"Bankdrukken","en":"Bench press","de":"Bankdrücken"}'::jsonb, '{"nl":"Lig op de bank, schouderbladen naar achteren. Laat de halter gecontroleerd zakken tot je borst en druk hem in een rechte lijn omhoog.","en":"Lie on the bench with your shoulder blades pulled back. Lower the bar under control to your chest and press it up in a straight line.","de":"Leg dich auf die Bank, Schulterblätter zurück. Senke die Hantel kontrolliert zur Brust und drück sie gerade nach oben."}'::jsonb, 'compound', 'external', 'barbell', array['chest']::text[], array['triceps', 'shoulders']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
