values ('b82bfa84-f914-597c-b035-ef3e68c5b87f', null, '{"nl":"Roemeense deadlift","en":"Romanian deadlift","de":"Rumänisches Kreuzheben"}'::jsonb, '{"nl":"Sta rechtop met de halter. Duw je heupen naar achteren met licht gebogen knieën tot je de rek in je hamstrings voelt, en kom weer omhoog.","en":"Stand tall with the bar. Push your hips back with slightly bent knees until you feel the stretch in your hamstrings, then come back up.","de":"Steh aufrecht mit der Hantel. Schieb die Hüfte mit leicht gebeugten Knien nach hinten, bis du die Dehnung im Beinbeuger spürst, und komm wieder hoch."}'::jsonb, 'compound', 'external', 'barbell', array['hamstrings', 'glutes']::text[], array['back']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
