values ('49e642b3-ae7f-51c6-be57-065def2ab22d', null, '{"nl":"Borstpers","en":"Machine chest press","de":"Brustpresse"}'::jsonb, '{"nl":"Handgrepen op borsthoogte. Druk ze naar voren tot je armen bijna gestrekt zijn en laat ze langzaam terugkomen.","en":"Handles at chest height. Press them forward until your arms are almost straight and let them come back slowly.","de":"Griffe auf Brusthöhe. Drück sie nach vorn, bis die Arme fast gestreckt sind, und lass sie langsam zurück."}'::jsonb, 'compound', 'external', 'machine', array['chest']::text[], array['triceps']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
