values ('1fe5089d-ed9a-5992-9d60-36a565d1d371', null, '{"nl":"Lat pulldown","en":"Lat pulldown","de":"Latziehen"}'::jsonb, '{"nl":"Pak de stang breed vast. Trek hem naar je bovenborst met je ellebogen naar beneden en laat hem gecontroleerd terug.","en":"Take a wide grip on the bar. Pull it to your upper chest, elbows down, and let it return under control.","de":"Greif die Stange breit. Zieh sie zur oberen Brust, Ellbogen nach unten, und lass sie kontrolliert zurück."}'::jsonb, 'compound', 'external', 'cable', array['back']::text[], array['biceps']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
