values ('61d7882e-01d3-57c2-9d63-76f62cbba0c1', null, '{"nl":"Roeien aan de kabel","en":"Seated cable row","de":"Rudern am Kabel"}'::jsonb, '{"nl":"Zit rechtop met licht gebogen knieën. Trek de greep naar je buik, schouderbladen naar elkaar, en laat hem langzaam terug.","en":"Sit upright with slightly bent knees. Pull the handle to your belly, shoulder blades together, and let it return slowly.","de":"Sitz aufrecht mit leicht gebeugten Knien. Zieh den Griff zum Bauch, Schulterblätter zusammen, und lass ihn langsam zurück."}'::jsonb, 'compound', 'external', 'cable', array['back']::text[], array['biceps']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
