values ('183f32fa-34d0-5281-bd2e-1c37ed5ef93d', null, '{"nl":"Smal bankdrukken","en":"Close-grip bench press","de":"Enges Bankdrücken"}'::jsonb, '{"nl":"Pak de halter op schouderbreedte. Laat hem naar je onderborst zakken met je ellebogen langs je lijf en druk hem omhoog.","en":"Grip the bar at shoulder width. Lower it to your lower chest with your elbows along your body and press it up.","de":"Greif die Hantel schulterbreit. Senke sie mit den Ellbogen am Körper zur unteren Brust und drück sie hoch."}'::jsonb, 'compound', 'external', 'barbell', array['triceps']::text[], array['chest', 'shoulders']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
