values ('e89da854-a8f5-5cdf-b2e2-9817f1142006', null, '{"nl":"Triceps liggend met halter","en":"Skull crusher","de":"French Press liegend"}'::jsonb, '{"nl":"Lig met de halter boven je schouders. Buig alleen je ellebogen tot de stang vlak achter je kruin is en strek weer uit.","en":"Lie with the bar over your shoulders. Bend only your elbows until the bar is just behind the top of your head and extend again.","de":"Lieg mit der Hantel über den Schultern. Beug nur die Ellbogen, bis die Stange knapp hinter dem Scheitel ist, und streck wieder."}'::jsonb, 'isolation', 'external', 'barbell', array['triceps']::text[], array['forearms']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
