values ('1292f064-1fed-5285-ba61-6ae18b316f62', null, '{"nl":"Smal opdrukken","en":"Diamond push-up","de":"Enge Liegestütze"}'::jsonb, '{"nl":"Zet je handen dicht bij elkaar onder je borst. Zak met je ellebogen langs je lijf en druk je in een rechte lijn op.","en":"Place your hands close together under your chest. Lower with your elbows along your body and push up in a straight line.","de":"Setz die Hände eng zusammen unter die Brust. Senke dich mit den Ellbogen am Körper und drück dich in einer Linie hoch."}'::jsonb, 'compound', 'bodyweight', 'bodyweight', array['triceps']::text[], array['chest', 'shoulders', 'core']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
