values ('80a936f7-847b-5fae-899e-fb110338e60b', null, '{"nl":"Dippen aan een bank","en":"Bench dip","de":"Dips an der Bank"}'::jsonb, '{"nl":"Steun met je handen achter je op de bankrand. Zak tot je ellebogen bijna haaks staan en druk jezelf omhoog.","en":"Support yourself with your hands behind you on the bench. Lower until your elbows are nearly at a right angle and push up.","de":"Stütz die Hände hinter dir auf die Bankkante. Senke dich, bis die Ellbogen fast rechtwinklig sind, und drück dich hoch."}'::jsonb, 'compound', 'bodyweight', 'bodyweight', array['triceps']::text[], array['chest', 'shoulders']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
