values ('3011f2fa-618d-57b2-a275-1fd0e1bee6ba', null, '{"nl":"Triceps boven het hoofd aan de kabel","en":"Overhead cable extension","de":"Trizepsstrecken über Kopf am Kabel"}'::jsonb, '{"nl":"Sta met je rug naar de kabel, touw achter je hoofd. Strek je armen naar voren en omhoog zonder je bovenarmen te laten zakken.","en":"Stand facing away from the cable, rope behind your head. Extend your arms forwards and up without dropping your upper arms.","de":"Steh mit dem Rücken zum Kabel, Seil hinter dem Kopf. Streck die Arme nach vorn oben, ohne die Oberarme zu senken."}'::jsonb, 'isolation', 'external', 'cable', array['triceps']::text[], array['core']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
