values ('560ac9b8-e837-511b-8fb3-f9f324fc78e5', null, '{"nl":"Biceps curl op een schuine bank","en":"Incline dumbbell curl","de":"Schrägbank-Curl"}'::jsonb, '{"nl":"Leun achterover op de schuine bank en laat je armen hangen. Krul de dumbbells omhoog zonder je bovenarmen te verplaatsen.","en":"Lean back on the incline bench and let your arms hang. Curl the dumbbells up without moving your upper arms.","de":"Lehn dich auf die Schrägbank und lass die Arme hängen. Beug die Kurzhanteln, ohne die Oberarme zu bewegen."}'::jsonb, 'isolation', 'external', 'dumbbell', array['biceps']::text[], array['forearms']::text[], 2, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
