values ('18bd08cc-aad6-50eb-8383-9387268ccf80', null, '{"nl":"Biceps curl aan de kabel","en":"Cable curl","de":"Kabel-Curl"}'::jsonb, '{"nl":"Sta voor de lage kabel met je ellebogen tegen je zij. Krul de stang omhoog en laat hem gecontroleerd zakken.","en":"Stand facing the low cable with your elbows at your sides. Curl the bar up and lower it under control.","de":"Steh vor dem tiefen Kabel, Ellbogen am Körper. Beug die Stange nach oben und senke sie kontrolliert."}'::jsonb, 'isolation', 'external', 'cable', array['biceps']::text[], array['forearms']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
