values ('e665d0e1-c7e8-5fa5-b179-4f32f3f648ef', null, '{"nl":"Omgekeerde polscurl","en":"Reverse wrist curl","de":"Umgekehrter Handgelenk-Curl"}'::jsonb, '{"nl":"Leg je onderarmen op een bank, handruggen omhoog. Til de lichte stang met alleen je polsen op en laat hem zakken.","en":"Rest your forearms on a bench, backs of your hands up. Lift the light bar with only your wrists and lower it.","de":"Leg die Unterarme auf eine Bank, Handrücken nach oben. Heb die leichte Stange nur mit den Handgelenken an und senke sie."}'::jsonb, 'isolation', 'external', 'barbell', array['forearms']::text[], array[]::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
