values ('348556d9-5805-5d13-b741-55966204d7e8', null, '{"nl":"Optrekken onderhands","en":"Chin-up","de":"Klimmzug im Untergriff"}'::jsonb, '{"nl":"Pak de stang smal vast met je handpalmen naar je toe. Trek je kin boven de stang en zak gecontroleerd tot gestrekte armen.","en":"Grip the bar narrowly with your palms towards you. Pull your chin over the bar and lower under control to straight arms.","de":"Greif die Stange eng, Handflächen zu dir. Zieh das Kinn über die Stange und senke dich kontrolliert bis zu gestreckten Armen."}'::jsonb, 'compound', 'bodyweight', 'bodyweight', array['back']::text[], array['biceps', 'core']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
