values ('78e41556-6413-5dd4-b7ff-9ea1f90f7b38', null, '{"nl":"Pulldown met gestrekte armen","en":"Straight-arm pulldown","de":"Überzüge am Kabel"}'::jsonb, '{"nl":"Sta licht voorover voor de hoge kabel. Duw de stang met bijna gestrekte armen in een boog naar je bovenbenen.","en":"Stand facing the high cable with a slight lean. Sweep the bar down to your thighs with almost straight arms.","de":"Steh leicht vorgebeugt vor dem hohen Kabel. Führ die Stange mit fast gestreckten Armen im Bogen zu den Oberschenkeln."}'::jsonb, 'isolation', 'external', 'cable', array['back']::text[], array['triceps', 'core']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
