values ('bfd33652-585c-5bcf-95a2-056e66be325d', null, '{"nl":"T-bar roeien","en":"T-bar row","de":"T-Bar-Rudern"}'::jsonb, '{"nl":"Sta over de stang en buig voorover met een rechte rug. Trek de schijven naar je borst en laat ze langzaam zakken.","en":"Straddle the bar and hinge forward with a straight back. Pull the plates to your chest and lower them slowly.","de":"Steh über der Stange und beug dich mit geradem Rücken vor. Zieh die Scheiben zur Brust und senke sie langsam."}'::jsonb, 'compound', 'external', 'barbell', array['back']::text[], array['biceps', 'hamstrings']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
