values ('2191cd07-bcf2-55ec-8f03-407ee2f0d5ad', null, '{"nl":"Voorovergebogen roeien met dumbbells","en":"Bent-over dumbbell row","de":"Vorgebeugtes Kurzhantelrudern"}'::jsonb, '{"nl":"Buig voorover met een rechte rug en een dumbbell in elke hand. Trek ze naar je heupen en laat ze langzaam zakken.","en":"Hinge forward with a straight back and a dumbbell in each hand. Pull them to your hips and lower them slowly.","de":"Beug dich mit geradem Rücken vor, eine Kurzhantel in jeder Hand. Zieh sie zur Hüfte und senke sie langsam."}'::jsonb, 'compound', 'external', 'dumbbell', array['back']::text[], array['biceps', 'hamstrings']::text[], 2, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
