values ('50925788-c719-5c26-8ad0-7c440769155b', null, '{"nl":"Squat zonder gewicht","en":"Bodyweight squat","de":"Kniebeuge ohne Gewicht"}'::jsonb, '{"nl":"Zet je voeten op schouderbreedte en steek je armen vooruit. Zak tot je heupen op kniehoogte zijn en kom rechtop.","en":"Stand with feet shoulder-width apart and arms out in front. Lower until your hips are at knee height and stand up.","de":"Stell die Füße schulterbreit, Arme nach vorn. Senke dich, bis die Hüfte auf Kniehöhe ist, und komm hoch."}'::jsonb, 'compound', 'bodyweight', 'bodyweight', array['quads', 'glutes']::text[], array['core']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
