values ('c539be1b-59bf-526a-bef1-b631cfe8cc50', null, '{"nl":"Hack squat","en":"Hack squat","de":"Hackenschmidt-Kniebeuge"}'::jsonb, '{"nl":"Leun met je rug tegen de slee, voeten voor je op het plateau. Zak diep met je rug tegen het kussen en druk je omhoog.","en":"Lean back against the sled, feet in front on the platform. Lower deep with your back on the pad and push up.","de":"Lehn dich an den Schlitten, Füße vorn auf der Platte. Geh mit dem Rücken am Polster tief und drück dich hoch."}'::jsonb, 'compound', 'external', 'machine', array['quads']::text[], array['glutes']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
