values ('f7d06db9-2d74-59d4-b662-573d5c7fec1f', null, '{"nl":"Sumo squat met dumbbell","en":"Dumbbell sumo squat","de":"Sumo-Kniebeuge mit Kurzhantel"}'::jsonb, '{"nl":"Sta breed met je tenen naar buiten en de dumbbell tussen je benen. Zak met een rechte rug en duw je knieën naar buiten.","en":"Stand wide, toes out, the dumbbell between your legs. Lower with a straight back, pushing your knees out.","de":"Steh breit, Zehen nach außen, Kurzhantel zwischen den Beinen. Senke dich mit geradem Rücken, die Knie nach außen."}'::jsonb, 'compound', 'external', 'dumbbell', array['glutes', 'quads']::text[], array['hamstrings']::text[], 2, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
