values ('9f20303e-a293-58c4-a4ed-f8f45bd4a47d', null, '{"nl":"Split squat","en":"Split squat","de":"Ausfallkniebeuge"}'::jsonb, '{"nl":"Sta in een grote schredestand. Zak recht omlaag tot je achterste knie bijna de grond raakt en kom omhoog zonder te stappen.","en":"Stand in a long split stance. Lower straight down until your back knee almost touches the floor and rise without stepping.","de":"Steh in weiter Schrittstellung. Senke dich, bis das hintere Knie fast den Boden berührt, und komm ohne Schritt hoch."}'::jsonb, 'compound', 'bodyweight', 'bodyweight', array['quads', 'glutes']::text[], array['hamstrings']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
