values ('e841fd41-f9be-5973-9dd0-4bf0a673f846', null, '{"nl":"Achterwaartse lunge","en":"Reverse lunge","de":"Ausfallschritt rückwärts"}'::jsonb, '{"nl":"Stap ver naar achteren en zak tot je knie bijna de grond raakt. Duw je met je voorste been terug en wissel.","en":"Take a long step back and lower until your knee almost touches the floor. Push back with your front leg and switch.","de":"Mach einen weiten Schritt zurück, bis das Knie fast den Boden berührt. Drück dich mit dem vorderen Bein zurück und wechsle."}'::jsonb, 'compound', 'bodyweight', 'bodyweight', array['quads', 'glutes']::text[], array['hamstrings']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
