values ('16706a53-e9c0-5375-a902-56c53a205f3b', null, '{"nl":"Sumo deadlift","en":"Sumo deadlift","de":"Sumo-Kreuzheben"}'::jsonb, '{"nl":"Sta breed met je tenen naar buiten en pak de halter tussen je benen. Kom met een rechte rug omhoog tot je rechtop staat.","en":"Stand wide, toes out, and grip the bar between your legs. Rise with a straight back until you stand tall.","de":"Steh breit, Zehen nach außen, und greif zwischen den Beinen. Komm mit geradem Rücken hoch, bis du aufrecht stehst."}'::jsonb, 'compound', 'external', 'barbell', array['glutes', 'hamstrings']::text[], array['quads', 'back']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
