values ('f12df4b1-986c-5d5b-87c6-f5c6398ea632', null, '{"nl":"Roemeense deadlift met dumbbells","en":"Dumbbell Romanian deadlift","de":"Rumänisches Kreuzheben mit Kurzhanteln"}'::jsonb, '{"nl":"Houd je knieën licht gebogen. Duw je heupen naar achteren met de dumbbells langs je benen tot je rek voelt en kom omhoog.","en":"Keep your knees slightly bent. Push your hips back, dumbbells along your legs, until you feel a stretch, then stand up.","de":"Halte die Knie leicht gebeugt. Schieb die Hüfte zurück, Kurzhanteln an den Beinen, bis du Dehnung spürst, und komm hoch."}'::jsonb, 'compound', 'external', 'dumbbell', array['hamstrings']::text[], array['glutes', 'back']::text[], 2, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
