values ('9611078e-dadb-5eed-975e-d100a7a93aed', null, '{"nl":"Deadlift met kettlebell","en":"Kettlebell deadlift","de":"Kreuzheben mit Kettlebell"}'::jsonb, '{"nl":"Zet de kettlebell tussen je voeten en pak hem met twee handen. Sta met een rechte rug op en zet hem rustig terug.","en":"Place the kettlebell between your feet and grip it with both hands. Stand up with a straight back and set it down slowly.","de":"Stell die Kettlebell zwischen die Füße und greif mit beiden Händen. Steh mit geradem Rücken auf und stell sie langsam ab."}'::jsonb, 'compound', 'external', 'kettlebell', array['glutes', 'hamstrings']::text[], array['quads', 'back']::text[], 4, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
