values ('6c409517-2328-571d-a156-0043e3c2a3c2', null, '{"nl":"Roemeense deadlift op één been","en":"Single-leg Romanian deadlift","de":"Einbeiniges Kreuzheben"}'::jsonb, '{"nl":"Sta op één been met een licht gebogen knie. Kantel voorover terwijl je vrije been naar achteren gaat en kom weer rechtop.","en":"Stand on one leg with a slightly bent knee. Tip forwards as your free leg goes back, then stand tall again.","de":"Steh auf einem Bein, das Knie leicht gebeugt. Kipp nach vorn, das freie Bein nach hinten, und richte dich wieder auf."}'::jsonb, 'compound', 'external', 'dumbbell', array['hamstrings']::text[], array['glutes', 'core']::text[], 2, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
