values ('7545ea47-371f-5840-b3fa-5d4913ba74c4', null, '{"nl":"Glute bridge","en":"Glute bridge","de":"Beckenheben"}'::jsonb, '{"nl":"Lig op je rug met je knieën gebogen. Duw je heupen omhoog tot een rechte lijn en laat ze langzaam zakken.","en":"Lie on your back with your knees bent. Push your hips up into a straight line and lower them slowly.","de":"Lieg auf dem Rücken, Knie gebeugt. Heb die Hüfte bis zu einer geraden Linie und senke sie langsam."}'::jsonb, 'isolation', 'bodyweight', 'bodyweight', array['glutes']::text[], array['hamstrings', 'core']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
