values ('6d711ed1-415e-563d-8168-8680ec44f6da', null, '{"nl":"Glute bridge op één been","en":"Single-leg glute bridge","de":"Einbeiniges Beckenheben"}'::jsonb, '{"nl":"Lig op je rug, één voet op de grond en het andere been gestrekt. Duw je heupen omhoog, houd ze recht en wissel daarna.","en":"Lie on your back, one foot on the floor and the other leg straight. Push your hips up, keep them level, then switch.","de":"Lieg auf dem Rücken, ein Fuß am Boden, das andere Bein gestreckt. Heb die Hüfte gerade an und wechsle danach."}'::jsonb, 'isolation', 'bodyweight', 'bodyweight', array['glutes']::text[], array['hamstrings', 'core']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
