values ('1748d1a5-11ae-514d-8d89-630041b5c4e3', null, '{"nl":"Kickback aan de kabel","en":"Cable kickback","de":"Kickbacks am Kabel"}'::jsonb, '{"nl":"Maak de band om je enkel vast en houd je vast aan het frame. Strek je been naar achteren zonder je onderrug hol te trekken.","en":"Fasten the strap round your ankle and hold the frame. Extend your leg back without arching your lower back.","de":"Befestige die Schlaufe am Knöchel und halte dich fest. Streck das Bein nach hinten, ohne ins Hohlkreuz zu gehen."}'::jsonb, 'isolation', 'external', 'cable', array['glutes']::text[], array['hamstrings']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
