values ('87009a54-e35f-56b4-8176-da31b534aba1', null, '{"nl":"Pull-through aan de kabel","en":"Cable pull-through","de":"Pull-Through am Kabel"}'::jsonb, '{"nl":"Sta met je rug naar de lage kabel, touw tussen je benen. Duw je heupen naar achteren en strek ze daarna krachtig.","en":"Stand facing away from the low cable, rope between your legs. Push your hips back, then extend them firmly.","de":"Steh mit dem Rücken zum tiefen Kabel, Seil zwischen den Beinen. Schieb die Hüfte zurück und streck sie dann kräftig."}'::jsonb, 'isolation', 'external', 'cable', array['glutes']::text[], array['hamstrings']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
