values ('158952f6-eb57-5784-a07d-adb32f11b7be', null, '{"nl":"Fietscrunch","en":"Bicycle crunch","de":"Fahrrad-Crunch"}'::jsonb, '{"nl":"Lig met je handen bij je hoofd. Draai je schouder naar de andere knie terwijl je het vrije been strekt en wissel rustig.","en":"Lie with your hands by your head. Turn your shoulder to the opposite knee as you extend the free leg and switch slowly.","de":"Lieg mit den Händen am Kopf. Dreh die Schulter zum anderen Knie, streck das freie Bein und wechsle ruhig."}'::jsonb, 'isolation', 'bodyweight', 'bodyweight', array['core']::text[], array[]::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
