insert into public.exercises (id, owner_id, name, instructions, kind, load_type, equipment, primary_muscles, secondary_muscles, default_step_kg, updated_at)
values ('9d515a55-fdd4-5b19-a5a6-792cc4dd880a', null, '{"nl":"Russische twist","en":"Russian twist","de":"Russian Twist"}'::jsonb, '{"nl":"Zit iets achterover met je knieën gebogen. Draai je schouders en handen van de ene naar de andere kant.","en":"Sit leaning back slightly with your knees bent. Turn your shoulders and hands from one side to the other.","de":"Sitz leicht zurückgelehnt, Knie gebeugt. Dreh Schultern und Hände von einer Seite zur anderen."}'::jsonb, 'isolation', 'bodyweight', 'bodyweight', array['core']::text[], array[]::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
