values ('d07c7f5b-89c1-581e-a706-c4dc3bb33767', null, '{"nl":"Dead bug","en":"Dead bug","de":"Dead Bug"}'::jsonb, '{"nl":"Lig met je armen omhoog en knieën boven je heupen. Strek een arm en het andere been uit met je onderrug op de grond en wissel.","en":"Lie with arms up and knees over your hips. Extend one arm and the opposite leg, lower back on the floor, and switch.","de":"Lieg mit Armen nach oben, Knie über der Hüfte. Streck einen Arm und das andere Bein, unterer Rücken am Boden, und wechsle."}'::jsonb, 'isolation', 'bodyweight', 'bodyweight', array['core']::text[], array[]::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
