insert into public.exercises (id, owner_id, name, instructions, kind, load_type, equipment, primary_muscles, secondary_muscles, default_step_kg, updated_at)
values ('82ea7913-73d8-5829-b318-407228680997', null, '{"nl":"Bird dog","en":"Bird dog","de":"Bird Dog"}'::jsonb, '{"nl":"Steun op handen en knieën. Strek een arm en het andere been uit zonder je heupen te draaien en wissel.","en":"Support yourself on hands and knees. Extend one arm and the opposite leg without turning your hips, then switch.","de":"Stütz dich auf Hände und Knie. Streck einen Arm und das andere Bein, ohne die Hüfte zu drehen, und wechsle."}'::jsonb, 'isolation', 'bodyweight', 'bodyweight', array['core']::text[], array['glutes', 'back']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
