values ('b8d245ed-7271-55fe-ab98-4884370d8c14', null, '{"nl":"Mountain climber","en":"Mountain climber","de":"Bergsteiger"}'::jsonb, '{"nl":"Steun met gestrekte armen in een plank. Trek om en om een knie naar je borst met je heupen laag.","en":"Hold a plank on straight arms. Draw one knee at a time to your chest with your hips low.","de":"Halte den Stütz mit gestreckten Armen. Zieh abwechselnd ein Knie zur Brust, die Hüfte tief."}'::jsonb, 'isolation', 'bodyweight', 'bodyweight', array['core']::text[], array['shoulders', 'quads']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
