insert into public.exercises (id, owner_id, name, instructions, kind, load_type, equipment, primary_muscles, secondary_muscles, default_step_kg, updated_at)
values ('70d3b706-7bfd-52c2-bdf4-34c4cc9854a0', null, '{"nl":"Buikwiel","en":"Ab wheel rollout","de":"Bauchroller"}'::jsonb, '{"nl":"Kniel met het wiel onder je schouders. Rol naar voren zover je onderrug recht blijft en trek jezelf terug.","en":"Kneel with the wheel under your shoulders. Roll forwards as far as your lower back stays straight and pull yourself back.","de":"Knie mit dem Rad unter den Schultern. Roll vor, solange der untere Rücken gerade bleibt, und zieh dich zurück."}'::jsonb, 'isolation', 'bodyweight', 'bodyweight', array['core']::text[], array['shoulders', 'back']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
