values ('ed122c54-849d-5995-987f-8849aaaa846b', null, '{"nl":"Pallof press","en":"Pallof press","de":"Pallof Press"}'::jsonb, '{"nl":"Sta zijwaarts naast de kabel met de greep voor je borst. Strek je armen vooruit zonder dat je romp meedraait.","en":"Stand side-on to the cable with the handle at your chest. Press your arms forwards without letting your torso turn.","de":"Steh seitlich zum Kabel, Griff vor der Brust. Streck die Arme nach vorn, ohne dass der Rumpf mitdreht."}'::jsonb, 'isolation', 'external', 'cable', array['core']::text[], array['shoulders']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
