values ('76f26c25-a784-55ba-8a33-91d96bffe330', null, '{"nl":"Houthakker aan de kabel","en":"Cable woodchop","de":"Holzhacker am Kabel"}'::jsonb, '{"nl":"Sta zijwaarts naast de hoge kabel. Trek de greep met gestrekte armen schuin omlaag langs je lijf en draai je romp mee.","en":"Stand side-on to the high cable. Pull the handle diagonally down across your body with straight arms, turning your torso.","de":"Steh seitlich zum hohen Kabel. Zieh den Griff mit gestreckten Armen diagonal am Körper vorbei und dreh den Rumpf mit."}'::jsonb, 'isolation', 'external', 'cable', array['core']::text[], array['shoulders']::text[], 5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
