values ('fc336ee8-bb09-54ac-9961-f911feb033b8', null, '{"nl":"Hangend knieën heffen","en":"Hanging knee raise","de":"Hängendes Knieheben"}'::jsonb, '{"nl":"Hang aan de stang. Breng je gebogen knieën boven heuphoogte zonder te zwaaien en laat ze langzaam zakken.","en":"Hang from the bar. Bring your bent knees above hip height without swinging and lower them slowly.","de":"Häng an der Stange. Bring die gebeugten Knie ohne Schwung über Hüfthöhe und senke sie langsam."}'::jsonb, 'isolation', 'bodyweight', 'bodyweight', array['core']::text[], array['forearms']::text[], 2.5, '2026-11-19T00:00:00Z'::timestamptz + interval '1 seconds')
